import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>BMP dosyaları devasadır. Bir BMP, aynı görselin JPG sürümünden on kat daha büyük olabilir.</p>\n<p>BMP, eski bir formattır ve sıkıştırma kullanmaz. Tarayıcılar ve eski yazılımlar onu üretir; modern dünya ise JPG ister.</p>\n<p>Bu kılavuz, BMP'nin neden bu kadar büyük olduğunu, JPG'ye dönüştürmenin yüzde 90 nasıl kazandırdığını ve taramalar ile toplu dosyalar için hangi ayarların işe yaradığını anlatıyor.</p>\n<h2 id=\"what-is-bmp\">BMP nedir?</h2>\n<p>BMP, bitmap demektir ve Windows'un eski görsel formatıdır. Pikselleri sıkıştırmadan, olduğu gibi saklar.</p>\n<p>BMP, 1990'larda standarttı. Paint ve eski tarayıcılar görselleri BMP olarak kaydederdi.</p>\n<p>Bugün BMP nadiren kullanılır. Modern formatlar aynı görseli çok daha küçük saklar.</p>\n<h2 id=\"why-bmp-is-huge\">BMP dosyaları neden bu kadar büyük?</h2>\n<p>BMP sıkıştırma kullanmaz. Her pikselin rengi tek tek, tam olarak saklanır; tekrar eden veri bile kısaltılmaz.</p>\n<p>Bir fotoğrafta milyonlarca piksel vardır. Her piksel üç bayt tutarsa dosya hızla onlarca MB olur.</p>\n<p>JPG ise akıllı sıkıştırma kullanır. Benzer pikselleri gruplar ve gereksiz ayrıntıyı atar; dosya onda birine iner.</p>\n<h2 id=\"how-conversion-works\">BMP'den JPG'ye dönüştürme nasıl çalışır?</h2>\n<p>Dönüştürücü, BMP'deki pikselleri okur ve JPG olarak yeniden kodlar. Görselin kendisi değişmez; yalnızca saklama biçimi değişir.</p>\n<p>İşlem tarayıcıda yapılır. Dosyanız cihazınızdan ayrılmaz; birkaç saniye içinde JPG kopyasını indirirsiniz.</p>\n<p>Kalite ayarı sizin elinizdedir. Yüzde 85, çoğu kullanımda gözle görülür fark yaratmadan büyük kazanç sağlar.</p>\n<h2 id=\"quality-settings\">İşe yarayan kalite ayarları</h2>\n<p>Fotoğraflar için kaliteyi yüzde 85 civarında tutun. Bu seviyede fark gözle görülmez ve dosya çok küçülür.</p>\n<p>Taramalar ve belgeler için yüzde 90 kullanın. Yazılar keskin kalmalıdır; düşük kalite okunabilirliği bozar.</p>\n<p>Ekran görüntüleri için yüzde 85 yeterlidir. Metin okunaklı kalır ve dosya belirgin küçülür.</p>\n<h2 id=\"colour-depth\">Renk derinliğine ne olur?</h2>\n<p>BMP'ler 1 bit, 8 bit ya da 24 bit olabilir. Dönüştürücü, renk derinliğini JPG'nin 24 bit yapısına çevirir.</p>\n<p>1 bit BMP'ler siyah beyazdır. JPG'ye dönüştürüldüğünde gri tonlar eklenebilir; bu normaldir.</p>\n<p>8 bit BMP'ler sınırlı renk paleti kullanır. JPG'ye dönüştürmede renkler korunur ama dosya büyüyebilir.</p>\n<h2 id=\"scanned-bmp-files\">Taranan BMP'ler neden bu kadar iyi sıkışır?</h2>\n<p>Taramalar genellikle beyaz arka plan ve siyah metin içerir. JPG bu basit yapıyı çok verimli sıkıştırır.</p>\n<p>Bir tarama BMP'si 10 MB ise JPG sürümü 500 KB olabilir. Kazanç yüzde 95'i bulur.</p>\n<p>Belge taramalarında kaliteyi yüzde 90 tutun. Yazılar keskin kalmalı; bulanık belge okunamaz.</p>\n<h2 id=\"transparency-myth\">BMP'de saydamlık var mı?</h2>\n<p>Hayır, BMP saydamlığı desteklemez. BMP'deki her piksel opak bir renge sahiptir.</p>\n<p>Saydam logo BMP olarak kaydedilemez. Saydamlık gerekiyorsa PNG kullanın.</p>\n<p>Bu, BMP'den JPG'ye geçişte sorun çıkarmaz. JPG de saydamlığı desteklemez; iki format bu konuda aynıdır.</p>\n<h2 id=\"batch-converting\">Bir klasör dolusu BMP taramasını toplu dönüştürmek</h2>\n<p>Eski tarayıcı klasörlerinde yüzlerce BMP olabilir. Tümünü aynı anda yükleyip toplu dönüştürün.</p>\n<p>Toplu dönüştürmede tüm dosyalar için aynı kalite ayarını kullanın. Tutarlılık, arşivi düzenli tutar.</p>\n<p>Sonuçları ZIP olarak indirin. Tek bir indirme, yüzlerce dosyayı düzenli biçimde almanızı sağlar.</p>\n<h2 id=\"checking-quality\">İndirmeden önce kaliteyi kontrol etmek</h2>\n<p>Her zaman önizlemeyle karşılaştırın. Orijinal BMP ile dönüştürülen JPG'yi yan yana açın.</p>\n<p>Yüzde 100 yakınlaştırmada inceleyin. Küçük yazılardaki bulanıklık ancak tam boyutta belli olur.</p>\n<p>Şüphede kalırsanız kaliteyi beş puan artırın. Birkaç KB fazladan boyut, okunamayan bir belgeden her zaman iyidir.</p>\n<h2 id=\"bmp-vs-png-decision\">BMP'den JPG'ye mi, BMP'den PNG'ye mi?</h2>\n<p>Fotoğraf ve tarama için JPG'yi seçin. Dosya çok daha küçük olur ve her yerde açılır.</p>\n<p>Çok keskin metin ya da çizim için PNG'yi seçin. PNG kayıpsızdır; yazılar her zaman keskin kalır.</p>\n<p>Arşiv için PNG, paylaşım için JPG kullanın. Her hedef kendi formatını alır.</p>\n<h2 id=\"where-jpg-works\">Dönüştürülen JPG nerede işe yarar?</h2>\n<p>Dönüştürülen JPG, JPG'nin kabul edildiği her yerde işe yarar. E-posta, formlar, web siteleri ve baskı merkezleri başlıca örneklerdir.</p>\n<p>Web sitesine BMP yükleyemezsiniz. Tarayıcılar BMP göstermez; JPG her tarayıcıda açılır.</p>\n<p>E-posta ekleri için JPG idealdir. Küçük dosya, hızlı gönderim demektir.</p>\n<h2 id=\"common-problems\">Yaygın sorunlar ve çözümler</h2>\n<p>Dosya yüklenmiyorsa boyut sınırını kontrol edin. Araç 20 MB'a kadar dosyaları kabul eder; daha büyük BMP'leri önce bölün.</p>\n<p>Çok eski BMP'ler açılmayabilir. 1 bit ya da 8 bit BMP'lerde dönüştürücü bazen zorlanır; dosyayı önce PNG'ye çevirmeyi deneyin.</p>\n<p>Dönüştürülen JPG bulanıksa kaliteyi artırın. Yüzde 90, belgeler için güvenli bir seviyedir.</p>\n<h2 id=\"bmp-from-old-scanners\">Eski tarayıcılardan BMP dosyaları</h2>\n<p>Eski tarayıcılar BMP üretir. Bu dosyalar genellikle büyüktür ama JPG'ye çok iyi sıkışır.</p>\n<p>Tarama klasörünü toplu dönüştürün. Yüzlerce dosya bir seferde hafifler.</p>\n<p>Orijinalleri arşivde saklayın. Taramalar tarihsel belge olabilir; orijinali silmeyin.</p>\n<h2 id=\"bmp-from-legacy-software\">Eski yazılımlardan BMP dosyaları</h2>\n<p>Eski yazılımlar görselleri BMP olarak kaydeder. Bu dosyalar, yazılımın ürettiği tek çıktı olabilir.</p>\n<p>Bu BMP'leri JPG'ye dönüştürün. Modern programlar BMP açmayabilir; JPG her yerde açılır.</p>\n<p>Dönüştürmeden önce dosyaları yedekleyin. Eski yazılımın çıktısı yeniden üretilemeyebilir.</p>\n<h2 id=\"bmp-screenshots-games\">Oyunlardan BMP ekran görüntüleri</h2>\n<p>Eski oyunlar ekran görüntüsünü BMP olarak kaydeder. Bu dosyalar büyüktür ama JPG'ye iyi sıkışır.</p>\n<p>Oyun ekran görüntüleri için kaliteyi yüzde 85 tutun. Arayüz yazıları okunaklı kalmalıdır.</p>\n<p>En sevdiğiniz görüntüleri arşivleyin. Oyun anıları, BMP klasörlerinde kaybolmamalıdır.</p>\n<h2 id=\"bmp-from-cameras\">Dijital kameralardan BMP dosyaları</h2>\n<p>Bazı eski kameralar BMP kaydeder. Bu dosyalar büyüktür ve kartı hızla doldurur.</p>\n<p>Kamera BMP'lerini JPG'ye dönüştürün. Fotoğraflar yüzde 90 küçülür ve kalite farkı görülmez.</p>\n<p>Orijinalleri arşivde saklayın. Fotoğraflar anıdır; orijinali silmeyin.</p>\n<h2 id=\"archiving-converted-jpgs-bmp\">Dönüştürülen JPG'leri arşivlemek</h2>\n<p>Dönüştürülen JPG'leri tarihe göre klasörleyin. Düzenli arşiv, ileride aramayı kolaylaştırır.</p>\n<p>Orijinal BMP'leri de saklayın. Dönüştürme tek yönlüdür; BMP'den JPG geri üretilemez.</p>\n<p>Arşivi yedekleyin. Harici disk ya da bulut depolama, arşivi güvende tutar.</p>\n<p>Özetle: BMP eski ve büyük, JPG küçük ve evrensel. Boyut karşılaştırması için <a href=\"/tr/blog/bmp-vs-jpg-dosya-boyutu\">BMP ve JPG dosya boyutu karşılaştırmasına</a> bakın; adımlar için <a href=\"/tr/blog/bmp-jpg-ye-nasil-donusturulur\">BMP JPG'ye nasıl dönüştürülür</a> yazısını okuyun. Dönüştürmek için <a href=\"/tr/bmp-jpg-ye-donustur\">BMP'den JPG'ye aracını</a> açın; genel dönüştürmeler için <a href=\"/tr/gorsel-donustur\">görsel dönüştürücü</a> de elinizin altındadır.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"BMP dosyaları JPG'ye göre neden bu kadar büyük?","answer":"Çünkü BMP sıkıştırma kullanmaz; her pikselin rengi tek tek, tam olarak saklanır. Bir fotoğrafta milyonlarca piksel vardır ve dosya hızla onlarca MB olur. JPG ise akıllı sıkıştırma kullanır; benzer pikselleri gruplar ve gereksiz ayrıntıyı atar."},{"question":"BMP'yi JPG'ye dönüştürerek ne kadar yer kazanmayı bekleyebilirim?","answer":"Genellikle yüzde 90 ya da daha fazla. 10 MB'lık bir BMP, yüzde 85 kaliteyle 1 MB'ın altına inebilir. Belge taramalarında kazanç yüzde 95'i bulur; beyaz arka plan ve siyah metin çok verimli sıkışır."},{"question":"Hangi kalite ayarı BMP ekran görüntülerini okunaklı tutar?","answer":"Yüzde 85-90 arası güvenlidir. Belgeler ve taramalar için yüzde 90 kullanın; yazılar keskin kalmalıdır. Fotoğraflar için yüzde 85 yeterlidir. Her zaman yüzde 100 yakınlaştırmayla kontrol edin."},{"question":"Kabul edilen en büyük BMP dosyası nedir?","answer":"Araç 20 MB'a kadar dosyaları kabul eder. Daha büyük BMP'lerle karşılaşırsanız dosyayı önce bölün ya da sıkıştırın. Çoğu tarama ve ekran görüntüsü bu sınırın altındadır."},{"question":"Eski 1 bit ya da 8 bit BMP dosyaları dönüştürülebilir mi?","answer":"Evet, çoğu durumda. 1 bit BMP'ler siyah beyazdır; JPG'ye dönüştürüldüğünde gri tonlar eklenebilir, bu normaldir. Çok eski ya da bozuk BMP'lerde dönüştürücü zorlanırsa dosyayı önce PNG'ye çevirmeyi deneyin."},{"question":"BMP'den JPG'ye, BMP'den PNG'ye göre ne zaman daha iyidir?","answer":"Fotoğraf, tarama ve paylaşım için JPG daha iyidir; dosya çok daha küçük olur ve her yerde açılır. Çok keskin metin ya da çizim için PNG daha iyidir; PNG kayıpsızdır ve yazıları her zaman keskin tutar."}];
